Here's a simple JavaScript function that accepts text and posts messages via the Slack API to the specified channel:

```javascript
const axios = require('axios');

async function postToSlack(text, channel) {
  const token = 'YOUR_SLACK_API_TOKEN'; // Replace with your Slack API token
  const url = `https://slack.com/api/chat.postMessage?token=${token}&channel=${channel}`;

  try {
    const response = await axios.post(url, {
      text,
    });

    console.log(`Message posted to ${channel}: ${text}`);
    return response.data;
  } catch (error) {
    console.error(`Error posting to Slack: ${error}`);
    throw error;
  }
}

// Example usage
postToSlack('Hello, world!', '#general').then((response) => {
  console.log(response);
}).catch((error) => {
  console.error(error);
});
```

Make sure to replace `YOUR_SLACK_API_TOKEN` with your actual Slack API token. Also, you can adjust the `channel` parameter to specify the channel where you want to post the message.

