<?php

function format_orders($orders) {
    $formatted_orders = array();

    foreach ($orders as $order) {
        $formatted_order = array(
            'date' => $order->get_date_created()->format('d/m/Y'),
            'order_number' => $order->get_order_number(),
            'customer_name' => $order->get_billing_first_name() . ' ' . $order->get_billing_last_name(),
            'total' => $order->get_total(),
            'tax_classes' => array(),
            'items' => array()
        );

        // Loop through order items
        foreach ($order->get_items() as $item) {
            $product_name = $item->get_name();
            $product_id = $item->get_product_id();
            $price = $item->get_total();
            $qty = $item->get_quantity();

            if ($item->is_taxable()) {
                $tax_class = $item->get_tax_class();
                $formatted_order['tax_classes'][] = "$tax_class";
            }

            $formatted_order['items'][] = "$product_name ($product_id) - $price x $qty";
        }

        $formatted_orders[] = $formatted_order;
    }

    return $formatted_orders;
}

