import Foundation

struct UserPreferences {
    let favoriteColor: String
    let preferredProductCategory: String
}

struct ProductReview {
    let productName: String
    let reviewText: String
    let rating: Int
}

func generateStatement(userPreferences: UserPreferences, productReviews: [ProductReview]) -> String {
    var statement = "Based on your preferences, you might like the following products:"

    // Filter products by category
    let filteredProducts = productReviews.filter { $0.productCategory == userPreferences.preferredProductCategory }

    // Sort products by rating
    let sortedProducts = filteredProducts.sorted { $0.rating > $1.rating }

    // Generate a list of recommended products
    var recommendedProducts = ""
    for i in 0..<3 {
        if i < sortedProducts.count {
            recommendedProducts += "\n- \(sortedProducts[i].productName)"
        } else {
            recommendedProducts += "\n- No matching products found."
        }
    }

    statement += recommendedProducts

    return statement
}

let userPreferences = UserPreferences(favoriteColor: "blue", preferredProductCategory: "electronics")
let productReviews = [
    ProductReview(productName: "iPhone 12", reviewText: "Great phone!", rating: 5),
    ProductReview(productName: "Samsung Galaxy S21", reviewText: "Awesome device!", rating: 4),
